// Тикет #b7a78c66 (b7a78c66d9b000fbc0f7d7cb) — עבר QA 13.10.2026, iPhone, TestFlight 1.0.0 (19).
// Факт 13.10: на главной большая надпись имени молитвы (StaticText, напр. «מנחה») видна целиком, верх букв не срезан
// и не перекрыт приветствием «…מוכן לתפילה מרוממת?» (скрины b7a78c66-ios-b19-home-mincha.png, b7a78c66-ios-b15-vs-b19-zoom.png).
// Автоматически — геометрия рамки; @manual-check: пиксельно верх букв (рамка может быть целой, а глифы срезаны line-height) — сверить по скрину.
import { driver, expect } from '@wdio/globals';
import { byLabel, byTextContains } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { rectOf, staticText } from '../_lib/app-1310.ts';
import { shown } from '../_lib/app-0710.ts';

const PRAYER_NAMES = ['שחרית', 'מנחה', 'ערבית'];

describe('Главная', () => {
  afterEach(async () => { await toHome(); });

  it('HM-04 Имя молитвы на главной не срезано сверху и не перекрыто приветствием #b7a78c66 @prod-safe @manual-check', async () => {
    await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });

    // 1. Крупная надпись — StaticText с точным именем текущей/ближайшей молитвы.
    let nameEl: ReturnType<typeof staticText> | undefined;
    let name = '';
    for (const n of PRAYER_NAMES) {
      const el = staticText(n);
      if (await shown(el)) { nameEl = el; name = n; break; }
    }
    expect(nameEl).toBeTruthy();
    const r = await rectOf(nameEl!);
    const { width, height } = await driver.getWindowSize();

    // 2. Рамка целиком в пределах экрана.
    expect(r.x).toBeGreaterThanOrEqual(0);
    expect(r.y).toBeGreaterThanOrEqual(0);
    expect(r.x + r.width).toBeLessThanOrEqual(width + 1);
    expect(r.y + r.height).toBeLessThanOrEqual(height);
    expect(r.height).toBeGreaterThan(0);

    // 3. Не перекрыта приветствием: верх имени ниже низа строки «…מוכן לתפילה מרוממת?».
    const greet = await byTextContains('מוכן לתפילה מרוממת?');
    await expect(greet).toBeDisplayed();
    const g = await rectOf(greet);
    expect(r.y).toBeGreaterThan(g.y + g.height - 1);
    console.log(`[HM-04] «${name}» y=${r.y} h=${r.height}; приветствие низ=${g.y + g.height}. @manual-check: верх букв на скрине не срезан.`);
  });
});
